  const translations = {};
  for (const [locale, values] of Object.entries(rows)) {
    if (values.length !== keys.length) throw new Error(`Project translations incomplete: ${locale}`);
    const pack = {};
    for (const [index, key] of keys.entries()) {
      const value = values[index];
      if (typeof value !== "string" || !value.trim()) throw new Error(`Project translation empty: ${locale}.${key}`);
      pack[key] = value;
    }
    translations[locale] = pack;
  }
  function message(locale, key) {
    return Object.hasOwn(translations, locale) && Object.hasOwn(translations[locale], key)
      ? translations[locale][key] : key;
  }
  function coverage(locale) {
    const pack = Object.hasOwn(translations, locale) ? translations[locale] : {};
    const missing = keys.filter((key) => !Object.hasOwn(pack, key));
    return { total: keys.length, translated: keys.length - missing.length, missing };
  }
  window.ParliamentStreamsProjectI18n = { message, coverage };
